using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using LighFight.Runtime;
public static class NativeSupportMainProbeBuilder {
 public static void Build(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var probe=new GameObject("Integrated native support EOF probe").AddComponent<NativeSupportMainProbe>();probe.prefabs=new[]{"Rose","Island","Ranger","Bone","Master"}.Select(w=>AssetDatabase.LoadAssetAtPath<GameObject>("Assets/LighFight/Art/Drafts/"+(w=="Rose"?"TripoPlayable":"Tripo"+w+"Playable")+"/"+w+"HumanoidCandidate.prefab")).ToArray();if(probe.prefabs.Any(p=>!p))throw new Exception("Main prefab missing");probe.footSets=probe.prefabs.Select(p=>{string prefabPath=AssetDatabase.GetAssetPath(p),prefabName=p.name;var skin=p.GetComponentInChildren<SkinnedMeshRenderer>();var mesh=skin.sharedMesh;var importer=(ModelImporter)AssetImporter.GetAtPath(AssetDatabase.GetAssetPath(mesh));bool readable=importer.isReadable;try{if(!readable){importer.isReadable=true;importer.SaveAndReimport();skin=AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath).GetComponentInChildren<SkinnedMeshRenderer>();mesh=skin.sharedMesh;}var rest=mesh.vertices;float lo=rest.Min(v=>skin.transform.TransformPoint(v).y),hi=rest.Max(v=>skin.transform.TransformPoint(v).y);var indices=new System.Collections.Generic.List<int>();using(var counts=mesh.GetBonesPerVertex())using(var weights=mesh.GetAllBoneWeights()){int offset=0;for(int i=0;i<rest.Length;i++){bool foot=skin.transform.TransformPoint(rest[i]).y<=lo+.13f*(hi-lo);for(int n=0;n<counts[i];n++){var w=weights[offset++];string name=skin.bones[w.boneIndex].name;if(w.weight>0&&(name.Contains("Foot")||name.Contains("Toe")))foot=true;}if(foot)indices.Add(i);}}return new NativeSupportMainProbe.FootSet{prefabName=prefabName,vertexCount=mesh.vertexCount,indices=indices.ToArray()};}finally{if(importer.isReadable!=readable){importer.isReadable=readable;importer.SaveAndReimport();}}}).ToArray();RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.45f,.43f,.4f);var key=new GameObject("Main key").AddComponent<Light>();key.type=LightType.Directional;key.intensity=1.2f;key.transform.rotation=Quaternion.Euler(45,-30,0);var camera=new GameObject("Main HDR evidence camera").AddComponent<Camera>();camera.orthographic=true;camera.orthographicSize=1.6f;camera.allowHDR=true;camera.transform.position=new Vector3(.98f,1.85f,4.9f);camera.transform.LookAt(new Vector3(0,1.35f,0));camera.backgroundColor=new Color(.1f,.12f,.15f);camera.clearFlags=CameraClearFlags.SolidColor;var fx=camera.gameObject.AddComponent<FittedFilmicCamera>();fx.filmicShader=AssetDatabase.LoadAssetAtPath<Shader>("Assets/LighFight/Resources/Shaders/FittedFilmic.shader");string rtPath="Assets/NativeSupport/MainIntegrationProbe.renderTexture";AssetDatabase.DeleteAsset(rtPath);var rt=new RenderTexture(800,1000,24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.sRGB);AssetDatabase.CreateAsset(rt,rtPath);camera.targetTexture=rt;probe.captureCamera=camera;var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.transform.position=new Vector3(0,-.025f,0);floor.transform.localScale=new Vector3(5,.05f,5);string scene="Assets/NativeSupport/MainIntegrationProbe.unity";EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene(),scene);string output=Environment.GetEnvironmentVariable("LIGHTFIGHT_NATIVE_PROBE_BUILD")??"NativeSupportMainProbe.app";var result=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{scene},target=BuildTarget.StandaloneOSX,locationPathName=output,options=BuildOptions.Development});if(result.summary.result!=UnityEditor.Build.Reporting.BuildResult.Succeeded)throw new Exception("Native main probe build failed");Debug.Log("NATIVE_MAIN_PROBE_BUILT "+output);}
}
